input.command:
cd /home/user/rork-app

# ATOMIC OPERATION: re-auth + commit + deploy + verify in one script
# This avoids the token expiry issue that plagued earlier attempts
bun -e '
const fs = require("fs");

// Step 1: Re-auth
console.log("=== STEP 1: RE-AUTH ===");
const loginRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
});
const loginData = await loginRes.json();
if (!loginData.accessToken) {
  console.log("LOGIN FAILED:", JSON.stringify(loginData).slice(0, 200));
  process.exit(1);
}
const token = loginData.accessToken;
fs.writeFileSync("/tmp/owner_token.txt", token);
console.log("Token refreshed:", token.slice(0, 8) + "..." + token.slice(-4));

// Step 2: Verify current production state
console.log("\n=== STEP 2: VERIFY CURRENT STATE ===");
const healthRes = await fetch("https://ivx-holdings-platform.onrender.com/health");
const health = await healthRes.json();
console.log("Production SHA:", health.seniorDeveloperRuntime?.commitSha?.slice(0, 12));
console.log("Production status:", health.status);

const headRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({ action: "github_get_repo_head", confirm: true, confirmText: "", input: { branch: "main" } }),
});
const headData = await headRes.json();
console.log("GitHub HEAD:", headData.result?.headSha?.slice(0, 12));

// Step 3: Commit the modified backend file
console.log("\n=== STEP 3: COMMIT BACKEND CHANGES ===");
const modifiedContent = fs.readFileSync("backend/api/ivx-developer-deploy-control.ts", "utf8");
console.log("File size:", modifiedContent.length, "bytes");

const commitRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({
    action: "github_commit_multi_file",
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
    input: {
      branch: "main",
      message: "feat(developer-deploy): add github_create_release + github_upload_release_asset for permanent APK hosting via GitHub Releases",
      files: [{
        path: "backend/api/ivx-developer-deploy-control.ts",
        content: modifiedContent
      }]
    }
  }),
});
const commitData = await commitRes.json();
const newSha = commitData.result?.commitSha;
console.log("Commit SHA:", newSha?.slice(0, 12));
console.log("Commit ok:", commitData.ok);
if (!newSha) {
  console.log("Commit failed:", JSON.stringify(commitData).slice(0, 400));
  process.exit(1);
}
fs.writeFileSync("/tmp/latest_commit_sha.txt", newSha);

// Step 4: Trigger Render deploy
console.log("\n=== STEP 4: TRIGGER RENDER DEPLOY ===");
const deployRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({
    action: "render_trigger_deploy",
    confirm: true,
    confirmText: "CONFIRM_IVX_RENDER_DEPLOY",
    input: {}
  }),
});
const deployData = await deployRes.json();
console.log("Deploy triggered:", deployData.ok, "| deployId:", deployData.result?.deployId);

console.log("\n=== DONE — Deploy triggered, will poll in next step ===");
console.log("New commit SHA:", newSha.slice(0, 12));
' 2>&1

