input.command:
cd /home/user/rork-app

# Poll for deploy completion + verify new code is live
# Render free tier deploys take 50-90 seconds
echo "Waiting 60s for Render deploy to complete..."
sleep 60

# Check production health
curl -sS https://ivx-holdings-platform.onrender.com/health 2>/dev/null | bun -e '
try {
  const d = JSON.parse(await Bun.stdin.text());
  const sha = d.seniorDeveloperRuntime?.commitSha?.slice(0, 12);
  console.log("Production SHA:", sha);
  console.log("Status:", d.status);
  console.log("Boot time:", d.bootTime);
  if (sha === "7bd2e7e537e1" || sha?.startsWith("7bd2e7e")) {
    console.log("DEPLOY COMPLETE: New code is live!");
  } else {
    console.log("Still on old SHA, deploy may still be in progress");
  }
} catch(e) { console.log("Error:", e.message); }
' 2>&1

