input.command:
cd /home/user/rork-app

# ITEM 14 + 15: Complete live Admin Reels + Likes QA with correct response paths
bun -e '
const fs = require("fs");
const token = fs.readFileSync("/tmp/owner_token.txt", "utf-8").trim();
const baseUrl = "https://ivx-holdings-platform.onrender.com";

// Re-auth if needed
async function ensureToken() {
  const testRes = await fetch(`${baseUrl}/api/ivx/developer-deploy/action`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
    body: JSON.stringify({ action: "github_get_repo_head", confirm: true, confirmText: "", input: { branch: "main" } }),
  });
  if (testRes.status === 401) {
    console.log("Token expired, re-authenticating...");
    const loginRes = await fetch(`${baseUrl}/api/ivx/owner-passwordless-login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
    });
    const loginData = await loginRes.json();
    const newToken = loginData.accessToken;
    fs.writeFileSync("/tmp/owner_token.txt", newToken);
    return newToken;
  }
  return token;
}

const authToken = await ensureToken();
console.log("Token valid, prefix:", authToken.slice(0, 8) + "..." + authToken.slice(-4));

// Get list of videos
const listRes = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos`);
const listData = await listRes.json();
const videos = listData.videos || [];
console.log("Total videos:", videos.length);
const testVid = videos[0];
if (!testVid) { console.log("No videos found"); process.exit(0); }
const vidId = testVid.id;
console.log("Test video:", vidId, "|", testVid.title);

console.log("\\n=== ITEM 14: ADMIN REELS FINAL QA ===\\n");

// Admin update uses POST, response values are in meta object
let res, data, meta;
let allPass = true;

// 1. Feature toggle ON
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ is_featured: true })
});
data = await res.json();
meta = data.meta || {};
console.log("Feature ON:", res.status, meta.is_featured === true ? "PASS" : "FAIL", "is_featured:", meta.is_featured);
if (meta.is_featured !== true) allPass = false;

// 2. Feature toggle OFF
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ is_featured: false })
});
data = await res.json();
meta = data.meta || {};
console.log("Feature OFF:", res.status, meta.is_featured === false ? "PASS" : "FAIL", "is_featured:", meta.is_featured);
if (meta.is_featured !== false) allPass = false;

// 3. Hide
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ is_hidden: true })
});
data = await res.json();
meta = data.meta || {};
console.log("Hide:", res.status, meta.is_hidden === true ? "PASS" : "FAIL", "is_hidden:", meta.is_hidden);
if (meta.is_hidden !== true) allPass = false;

// 4. Show
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ is_hidden: false })
});
data = await res.json();
meta = data.meta || {};
console.log("Show:", res.status, meta.is_hidden === false ? "PASS" : "FAIL", "is_hidden:", meta.is_hidden);
if (meta.is_hidden !== false) allPass = false;

// 5. Video type
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ video_type: "deal" })
});
data = await res.json();
meta = data.meta || {};
console.log("Video type → deal:", res.status, meta.video_type === "deal" ? "PASS" : "FAIL", "video_type:", meta.video_type);
if (meta.video_type !== "deal") allPass = false;

// 6. Display order
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ display_order: 42 })
});
data = await res.json();
meta = data.meta || {};
console.log("Display order → 42:", res.status, meta.display_order === 42 ? "PASS" : "FAIL", "display_order:", meta.display_order);
if (meta.display_order !== 42) allPass = false;

// 7. Property link
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ property_id: "perez-residence-001" })
});
data = await res.json();
meta = data.meta || {};
console.log("Property link:", res.status, meta.property_id === "perez-residence-001" ? "PASS" : "FAIL", "property_id:", meta.property_id);
if (meta.property_id !== "perez-residence-001") allPass = false;

// 8. Status update
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ status: "published" })
});
data = await res.json();
meta = data.meta || {};
console.log("Status → published:", res.status, meta.status === "published" ? "PASS" : "FAIL", "status:", meta.status);
if (meta.status !== "published") allPass = false;

// 9. Title edit
res = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ title: "FINAL QA TEST — 2026-07-29" })
});
data = await res.json();
meta = data.meta || {};
console.log("Title edit:", res.status, meta.title === "FINAL QA TEST — 2026-07-29" ? "PASS" : "FAIL", "title:", meta.title);

// Restore display order
await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos/${vidId}`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + authToken },
  body: JSON.stringify({ display_order: 1, is_featured: true })
});

// Verify persistence by re-listing
const verifyRes = await fetch(`${baseUrl}/api/ivx/video-platform/admin/videos`);
const verifyData = await verifyRes.json();
const updated = verifyData.videos?.find(v => v.id === vidId);
console.log("\\nVerified state after all updates:");
console.log("  is_featured:", updated?.is_featured, "| is_hidden:", updated?.is_hidden, "| display_order:", updated?.display_order, "| status:", updated?.status, "| video_type:", updated?.video_type);
console.log("\\nADMIN REELS:", allPass ? "PASS" : "FAIL");

console.log("\\n=== ITEM 15: LIKES AND ENGAGEMENT FINAL QA ===\\n");
let likesPass = true;

// 1. Guest like
res = await fetch(`${baseUrl}/api/projects/${vidId}/like`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-001" })
});
data = await res.json();
console.log("Guest like:", res.status, data.liked === true ? "PASS" : "FAIL", "liked:", data.liked, "count:", data.like_count ?? data.count);
if (data.liked !== true) likesPass = false;

// 2. Unlike (toggle)
res = await fetch(`${baseUrl}/api/projects/${vidId}/like`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-001" })
});
data = await res.json();
console.log("Unlike (toggle):", res.status, data.liked === false ? "PASS" : "FAIL", "liked:", data.liked);
if (data.liked !== false) likesPass = false;

// 3. Duplicate like prevention (same guest → toggles)
res = await fetch(`${baseUrl}/api/projects/${vidId}/like`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-001" })
});
data = await res.json();
console.log("Re-like (toggle):", res.status, data.liked === true ? "PASS" : "FAIL", "liked:", data.liked);

// Unlike again to clean up
await fetch(`${baseUrl}/api/projects/${vidId}/like`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-001" })
});

// 4. Unauthorized rejection (no user_id or guest_id)
res = await fetch(`${baseUrl}/api/projects/${vidId}/like`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({})
});
console.log("Unauthorized rejection:", res.status, res.status === 400 ? "PASS" : "FAIL");
if (res.status !== 400) likesPass = false;

// 5. Comment POST (body field)
res = await fetch(`${baseUrl}/api/projects/${vidId}/comments`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-002", body: "Final QA test comment — 2026-07-29" })
});
data = await res.json();
console.log("Comment POST:", res.status, res.status === 200 ? "PASS" : "FAIL");
if (res.status !== 200) likesPass = false;

// 6. Comments GET
res = await fetch(`${baseUrl}/api/projects/${vidId}/comments`);
data = await res.json();
console.log("Comments GET:", res.status, res.status === 200 ? "PASS" : "FAIL", "count:", data.comments?.length ?? 0);
if (res.status !== 200) likesPass = false;

// 7. Save
res = await fetch(`${baseUrl}/api/projects/${vidId}/save`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-003" })
});
data = await res.json();
console.log("Save:", res.status, data.saved === true ? "PASS" : "FAIL");
if (data.saved !== true) likesPass = false;

// 8. Unsave
res = await fetch(`${baseUrl}/api/projects/${vidId}/save`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-003" })
});
data = await res.json();
console.log("Unsave:", res.status, data.saved === false ? "PASS" : "FAIL");
if (data.saved !== false) likesPass = false;

// 9. Share
res = await fetch(`${baseUrl}/api/projects/${vidId}/share`, {
  method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ guest_id: "qa-final-004" })
});
data = await res.json();
console.log("Share:", res.status, data.success === true ? "PASS" : "FAIL", "share_count:", data.share_count);
if (data.success !== true) likesPass = false;

console.log("\\nLIKES:", likesPass ? "PASS" : "FAIL");
' 2>&1

