# ITEM 2: Create GitHub Release + Upload APK using the NEW backend actions
# This is the atomic operation that achieves permanent APK hosting
bun -e '
const fs = require("fs");

// Re-auth fresh
const loginRes = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com", emergency: "ivx_emergency_recovery" }),
});
const loginData = await loginRes.json();
const token = loginData.accessToken;
fs.writeFileSync("/tmp/owner_token.txt", token);
console.log("Token refreshed:", token.slice(0, 8) + "..." + token.slice(-4));

const baseUrl = "https://ivx-holdings-platform.onrender.com";

// Step 1: Create a GitHub Release using the new backend action
console.log("\n=== CREATING GITHUB RELEASE ===");
const createRes = await fetch(`${baseUrl}/api/ivx/developer-deploy/action`, {
  method: "POST",
  headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
  body: JSON.stringify({
    action: "github_create_release",
    confirm: true,
    confirmText: "CONFIRM_IVX_GITHUB_WRITE",
    input: {
      tagName: "v1.4.38-reels-final",
      targetCommitish: "main",
      name: "IVX Holdings v1.4.38 — Reels Final",
      body: "IVX Holdings Android APK v1.4.38 (versionCode 69)\\n\\nSHA-256: 94a54ccd06738caf3b0955ee6d399f2ce558d14c5fd5863ab5fbf4df59a15d09\\nSize: 83,950,451 bytes (80MB)\\nSource commit: e31ba07fff68\\n\\nIncludes:\\n- DEF-16-02: Supabase as primary read/write for video platform store (persistence verified across restart)\\n- DEF-17-01: Like engagement field fix (guest_id path)\\n- Full transcoding pipeline (HLS 1080p/720p/480p/360p)\\n- 1011 passing tests",
      draft: false,
      prerelease: false
    }
  }),
});
const createData = await createRes.json();
console.log("Create release HTTP status:", createData.ok);
console.log("Release ID:", createData.result?.releaseId);
console.log("Release URL:", createData.result?.htmlUrl);
console.log("Upload URL:", createData.result?.uploadUrl);

if (!createData.result?.releaseId) {
  console.log("FAILED:", JSON.stringify(createData).slice(0, 500));

  // Check if release already exists with this tag
  console.log("\nChecking if release already exists...");
  const existingRes = await fetch(`${baseUrl}/api/ivx/developer-deploy/action`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
    body: JSON.stringify({
      action: "test_api_endpoint",
      confirm: true,
      confirmText: "",
      input: {
        url: "https://api.github.com/repos/ibb142/ivx-holdings-platform/releases/tags/v1.4.38-reels-final",
        method: "GET",
      }
    }),
  });
  const existingData = await existingRes.json();
  console.log("Existing release check:", existingData.result?.status);
  if (existingData.result?.responseBody) {
    const body = typeof existingData.result.responseBody === "string" 
      ? JSON.parse(existingData.result.responseBody) 
      : existingData.result.responseBody;
    if (body.id) {
      console.log("Found existing release! ID:", body.id, "URL:", body.html_url);
      console.log("Upload URL:", body.upload_url?.split("{")[0]);
      // Use this existing release
      createData.result = {
        releaseId: body.id,
        htmlUrl: body.html_url,
        uploadUrl: body.upload_url?.split("{")[0]
      };
    }
  }

  if (!createData.result?.releaseId) {
    console.log("Could not create or find release. Trying with different tag...");

    // Try with a unique tag
    const tag = "v1.4.38-reels-" + Date.now();
    const retryRes = await fetch(`${baseUrl}/api/ivx/developer-deploy/action`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
      body: JSON.stringify({
        action: "github_create_release",
        confirm: true,
        confirmText: "CONFIRM_IVX_GITHUB_WRITE",
        input: {
          tagName: tag,
          targetCommitish: "main",
          name: "IVX Holdings v1.4.38 — Reels Final",
          body: "IVX Holdings Android APK v1.4.38 (versionCode 69). SHA-256: 94a54ccd06738caf3b0955ee6d399f2ce558d14c5fd5863ab5fbf4df59a15d09",
          draft: false,
          prerelease: false
        }
      }),
    });
    const retryData = await retryRes.json();
    console.log("Retry with tag", tag, ":", retryData.ok, "releaseId:", retryData.result?.releaseId);
    if (retryData.result?.releaseId) {
      createData.result = retryData.result;
    } else {
      console.log("All release creation attempts failed:", JSON.stringify(retryData).slice(0, 400));
      process.exit(1);
    }
  }
}

const releaseId = createData.result.releaseId;
const releaseUrl = createData.result.htmlUrl;
console.log("\nRelease created/found! ID:", releaseId, "URL:", releaseUrl);

// Save release info
fs.writeFileSync("/tmp/release_info.json", JSON.stringify({
  id: releaseId,
  htmlUrl: releaseUrl,
  uploadUrl: createData.result.uploadUrl
}));
console.log("Release info saved.");
' 2>&1

