// Upload APK directly to GitHub Release using RORK_PUBLIC_GITHUB_TOKEN
// This avoids the Render 502 timeout by uploading from the sandbox directly

const token = process.env.RORK_PUBLIC_GITHUB_TOKEN;
if (!token) {
  console.log("NO RORK_PUBLIC_GITHUB_TOKEN in environment");
  console.log("Available env vars:", Object.keys(process.env).filter(k => k.includes("GITHUB") || k.includes("RORK")).join(", "));
  process.exit(1);
}

console.log("Token prefix:", token.slice(0, 10) + "..." + token.slice(-4));
console.log("Token length:", token.length);

// Verify token works
const repoRes = await fetch("https://api.github.com/repos/ibb142/ivx-holdings-platform", {
  headers: { Authorization: "token " + token, Accept: "application/vnd.github+json" }
});
const repoData = await repoRes.json();
console.log("Repo:", repoData.full_name, "| private:", repoData.private, "| push:", repoData.permissions?.push);

if (!repoData.permissions?.push) {
  console.log("ERROR: Token does not have push permission");
  process.exit(1);
}

// Read the APK from disk
const fs = await import("fs");
const apkPath = "/home/user/rork-app/expo/android/app/build/outputs/apk/release/app-release.apk";
const apkBuffer = fs.readFileSync(apkPath);
const crypto = await import("crypto");
const sha256 = crypto.createHash("sha256").update(apkBuffer).digest("hex");
console.log("\nAPK size:", apkBuffer.length, "bytes (" + (apkBuffer.length / 1048576).toFixed(1) + " MB)");
console.log("APK SHA-256:", sha256);

// First, list and delete any existing assets on the release
console.log("\n=== Cleaning up existing assets ===");
const assetsRes = await fetch("https://api.github.com/repos/ibb142/ivx-holdings-platform/releases/361740929/assets", {
  headers: { Authorization: "token " + token, Accept: "application/vnd.github+json" }
});
const assets = await assetsRes.json();
if (Array.isArray(assets)) {
  console.log("Existing assets:", assets.length);
  for (const a of assets) {
    console.log("  ID:", a.id, "| name:", a.name, "| size:", a.size, "bytes");
    console.log("  Deleting...");
    const delRes = await fetch(`https://api.github.com/repos/ibb142/ivx-holdings-platform/releases/361740929/assets/${a.id}`, {
      method: "DELETE",
      headers: { Authorization: "token " + token, Accept: "application/vnd.github+json" }
    });
    console.log("  Delete:", delRes.status);
